const server = Bun.serve({
  port: 0,
  fetch(req) {
    return new Response(`Hello from ${req.url}`);
  },
});
console.log(server.url.href);
server.stop();

const listener = Bun.listen({
  hostname: "127.0.0.1",
  port: 0,
  socket: { data(socket, data) { socket.write(`echo: ${data}`); } },
});
console.log(listener.port);
listener.stop();

const listener = Bun.listen({ hostname: "127.0.0.1", port: 0, socket: { data() {} } });
const socket = await Bun.connect({ hostname: "127.0.0.1", port: listener.port, socket: { data(s, d) { console.log(d.toString()); } } });
socket.write("ping");
await Bun.sleep(20);
socket.end();
listener.stop(true);

const server = await Bun.udpSocket({ hostname: "127.0.0.1", port: 0, socket: { data(s, d, p, a) { s.send("pong", p, a); } } });
const client = await Bun.udpSocket({ hostname: "127.0.0.1", port: 0, socket: {} });
client.send("ping", server.port, "127.0.0.1");
await Bun.sleep(50);
client.close();
server.close();
console.log("udp ping/pong done");

const res = await Bun.fetch("https://bun.com");
console.log(res.status, res.headers.get("content-type"));
console.log((await res.text()).length);

const file = Bun.file("./package.json");
console.log(file.type);
const pkg = await file.json();
console.log(pkg.name);

const bytes = await Bun.write("hello.txt", "Hello Bun!");
console.log(bytes);
console.log(await Bun.file("hello.txt").text());

const glob = new Bun.Glob("**/*.ts");
for await (const path of glob.scan({ cwd: import.meta.dir })) {
  console.log(path);
}

const mode = Bun.env.NODE_ENV ?? "development";
console.log(mode);
console.log(Object.keys(Bun.env).length);

const start = Bun.nanoseconds();
await Bun.sleep(10);
console.log(Bun.nanoseconds() - start, "ns");

const buf = new TextEncoder().encode("hello");
const str = Bun.unsafe.arrayBufferToString(buf);
console.log(str);
console.log(Bun.unsafe.memoryFootprint());

await Bun.secrets.set({ service: "my-app", name: "token", value: "s3cret" });
const token = await Bun.secrets.get({ service: "my-app", name: "token" });
console.log(token);
await Bun.secrets.delete({ service: "my-app", name: "token" });

if (Bun.isStandaloneExecutable) {
  for (const file of Bun.embeddedFiles) console.log(file.name);
}

const job = Bun.cron("*/5 * * * *", () => {
  console.log("tick");
});
console.log(job.cron);
job.stop();

