class Bun.ModuleGraph {
  constructor(options?: { globals?: Record<string, unknown>; onError?: (error: unknown, kind: "uncaughtException" | "unhandledRejection") => void });
  static readonly current: Bun.ModuleGraph | undefined;
  import<T = unknown>(specifier: string): Promise<T>;
  run<T>(callback: () => T): T;
  dispose(): void;
}

apis.example:
const tenantProcess = Object.create(process, { env: { value: { TENANT: "a" }, enumerable: true } });
const graph = new Bun.ModuleGraph({
  globals: { process: tenantProcess },
  onError: (error, kind) => console.error(kind, error),
});
const app = await graph.import("./app.ts");
console.log(await graph.run(() => app.handle()));
graph.dispose();

const proc = Bun.spawn(["bun", "--version"]);
const version = await new Response(proc.stdout).text();
await proc.exited;
console.log(version.trim());

const terminal = new Bun.Terminal({
  cols: 80,
  rows: 24,
  data(term, data) { process.stdout.write(data); },
});
const proc = Bun.spawn(["bun", "--version"], { terminal });
await proc.exited;
terminal.close();

const h = Bun.hash("hello world");
console.log(h.toString(16));
console.log(Bun.hash("hello world", 123n).toString(16));

const hasher = new Bun.CryptoHasher("sha256");
hasher.update("hello ");
hasher.update("world");
console.log(hasher.digest("hex"));

const id = Bun.randomUUIDv7();
console.log(id);
console.log(Bun.randomUUIDv7("base64url"));

const gz = Bun.gzipSync("hello world");
console.log(gz.byteLength);
console.log(new TextDecoder().decode(Bun.gunzipSync(gz)));

const archive = new Bun.Archive({ "hello.txt": "Hello, World!" }, { compress: "gzip" });
await Bun.write("archive.tar.gz", archive);
const files = await archive.files();
console.log([...files.keys()]);

const sql = new Bun.SQL("sqlite://:memory:");
const [row] = await sql`select 1 + 1 as two`;
console.log(row.two);
await sql.close();

import { Database } from "bun:sqlite";
const db = new Database(":memory:");
db.run("create table t (n int)");
db.run("insert into t values (1), (2)");
console.log(db.query("select count(*) as n from t").get());
db.close();

const redis = new Bun.RedisClient("redis://localhost:6379");
await redis.set("hello", "world");
console.log(await redis.get("hello"));
redis.close();

const bucket = new Bun.S3Client({ bucket: "my-bucket" });
const file = bucket.file("hello.txt");
await file.write("Hello Bun!");
console.log(await file.text());

const config = Bun.TOML.parse("[server]\nport = 3000");
console.log(config.server.port);
console.log(Bun.TOML.stringify(config));

const data = Bun.YAML.parse("name: bun\nversion: 1.4.4");
console.log(data.name);
console.log(Bun.YAML.stringify(data));

const result = await Bun.build({
  entrypoints: ["./index.ts"],
  outdir: "./dist",
});
console.log(result.success, result.outputs.length);

const transpiler = new Bun.Transpiler({ loader: "tsx" });
const { exports, imports } = transpiler.scan(`
import React from "react";
import type { ReactNode } from "react";
export const name = "hello";
`);
console.log(exports, imports);
