Bun.plugin({
  name: "txt-loader",
  setup(build) {
    const onLoad = async (args) => ({ contents: await Bun.file(args.path).text(), loader: "text" });
    build.onLoad({ filter: /\.txt$/ }, onLoad);
  },
});

